CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL, c1 REAL NOT NULL DEFAULT 0, c2 REAL, c3 REAL DEFAULT 'd', c4 INTEGER DEFAULT 'd') STRICT;
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 NUMERIC CHECK(c0 IS NULL OR length(c0) < 40), c1 REAL DEFAULT 'd', c2 VARCHAR(10) COLLATE NOCASE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(NULL, 'Ελλάδα', -3, 7);
SELECT date('2038-01-19 03:14:07'), time('2038-01-19 03:14:07'), datetime('2038-01-19 03:14:07', '+12 hours'), julianday('2038-01-19 03:14:07'), strftime('%s', '2038-01-19 03:14:07'), unixepoch('2038-01-19 03:14:07'), timediff('2024-03-01', '2023-01-15');
SELECT date('2000-01-01 12:34:56'), time('2000-01-01 12:34:56'), datetime('2000-01-01 12:34:56', 'unixepoch'), julianday('2000-01-01 12:34:56'), strftime('%j %w %W', '2000-01-01 12:34:56'), unixepoch('2000-01-01 12:34:56'), timediff('2024-03-01', '2023-01-15');
SELECT date(2451545.0), time(2451545.0), datetime(2451545.0, '-1 month'), julianday(2451545.0), strftime('%J', 2451545.0), unixepoch(2451545.0), timediff('2024-03-01', '2023-01-15');
SELECT date('2000-01-01 12:34:56'), time('2000-01-01 12:34:56'), datetime('2000-01-01 12:34:56', '+12 hours'), julianday('2000-01-01 12:34:56'), strftime('%f', '2000-01-01 12:34:56'), unixepoch('2000-01-01 12:34:56'), timediff('2024-03-01', '2023-01-15');
SELECT date('1970-01-01'), time('1970-01-01'), datetime('1970-01-01', '+1 year'), julianday('1970-01-01'), strftime('%s', '1970-01-01'), unixepoch('1970-01-01'), timediff('2024-03-01', '2023-01-15');
SELECT date(1700000000), time(1700000000), datetime(1700000000, 'unixepoch'), julianday(1700000000), strftime('%f', 1700000000), unixepoch(1700000000), timediff('2024-03-01', '2023-01-15');
SELECT a.id, b.id, a.c0, b.ref FROM t0 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 14;
SELECT count(*) FROM t0 a JOIN t0 b USING(id);
